cat > yaml_codec.py <<'PY'
"""Small ordered YAML reader/writer for tabular data.

Implements scalars, flow collections, indented collections and document streams
without depending on an external YAML installation.
"""
import re
import json
import math


def split_flow(s, delimiter=','):
    out, start, depth, quote = [], 0, 0, ''
    i = 0
    while i < len(s):
        c = s[i]
        if quote:
            if c == quote:
                if quote == "'" and i+1 < len(s) and s[i+1] == "'":
                    i += 1
                else:
                    quote = ''
            elif c == '\\' and quote == '"':
                i += 1
        elif c in "\"'":
            quote = c
        elif c in '[{(':
            depth += 1
        elif c in ']})':
            depth -= 1
        elif c == delimiter and depth == 0:
            out.append(s[start:i].strip())
            start = i+1
        i += 1
    out.append(s[start:].strip())
    return out


def mapping_pair(s):
    depth, quote = 0, ''
    for i, c in enumerate(s):
        if quote:
            if c == quote and (i == 0 or s[i-1] != '\\'):
                quote = ''
        elif c in "\"'":
            quote = c
        elif c in '[{':
            depth += 1
        elif c in ']}':
            depth -= 1
        elif c == ':' and depth == 0 and (i+1 == len(s) or s[i+1].isspace()):
            return s[:i], s[i+1:].strip()
    return None


def scalar(text):
    text = text.strip()
    if not text or text.lower() in ('null', '~'):
        return None
    if text[:1] == '"' and text[-1:] == '"':
        try:
            return json.loads(text)
        except Exception:
            return text[1:-1]
    if text[:1] == "'" and text[-1:] == "'":
        return text[1:-1].replace("''", "'")
    if text.startswith('[') and text.endswith(']'):
        return [scalar(v) for v in split_flow(text[1:-1])] if text[1:-1].strip() else []
    if text.startswith('{') and text.endswith('}'):
        out = {}
        for part in split_flow(text[1:-1]):
            if not part:
                continue
            pair = mapping_pair(part)
            if not pair and ':' in part:
                pair = part.split(':', 1)
            if pair:
                out[str(scalar(pair[0]))] = scalar(pair[1])
            else:
                out[str(scalar(part))] = None
        return out
    # Comments are only introduced at whitespace boundaries.
    text = re.split(r'\s+#', text, maxsplit=1)[0].rstrip()
    if text.lower() in ('true', 'false'):
        return text.lower() == 'true'
    n = text.replace('_', '')
    try:
        if re.fullmatch(r'[+-]?0[xX][\da-fA-F]+', n):
            return int(n, 16)
        if re.fullmatch(r'[+-]?0[oO][0-7]+', n):
            return int(n, 8)
        if re.fullmatch(r'[+-]?0[bB][01]+', n):
            return int(n, 2)
        if re.fullmatch(r'[+-]?\d+', n):
            if len(n.lstrip('+-')) > 1 and n.lstrip('+-').startswith('0') and re.fullmatch(r'[+-]?0[0-7]+', n):
                return int(n, 8)
            return int(n)
        if re.fullmatch(r'[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?', n):
            return float(n)
    except ValueError:
        pass
    if n.lower() in ('.inf', '+.inf', '-.inf', '.nan'):
        return float(n.lower().replace('.', ''))
    return text


def load_one(text):
    # Top-level flow expressions and scalar strings.
    stripped = text.strip()
    if not stripped:
        return None
    if stripped[0] in '[{' or (not mapping_pair(stripped.split('\n')[0]) and not stripped.startswith('- ')):
        if '\n' not in stripped or stripped[0] in '[{':
            return scalar(stripped)
        return scalar(' '.join(x.strip() for x in stripped.splitlines()))
    raw = text.expandtabs(2).splitlines()
    lines = []
    for s in raw:
        if not s.strip() or s.lstrip().startswith('#'):
            continue
        lines.append((len(s)-len(s.lstrip()), s.lstrip()))
    if not lines:
        return None

    def parse(index, indent):
        seq = lines[index][1] == '-' or lines[index][1].startswith('- ')
        result = [] if seq else {}
        while index < len(lines) and lines[index][0] == indent:
            s = lines[index][1]
            if seq:
                if not (s == '-' or s.startswith('- ')):
                    break
                val = s[1:].strip()
                index += 1
                p = mapping_pair(val)
                if p:
                    key, v = p
                    item = {}
                    key = str(scalar(key))
                    if v in ('|', '|-', '|+', '>', '>-', '>+'):
                        v, index = block(index, indent, v)
                        item[key] = v
                    elif v:
                        item[key] = scalar(v)
                    elif index < len(lines) and lines[index][0] > indent + 2:
                        item[key], index = parse(index, lines[index][0])
                    elif index < len(lines) and lines[index][0] >= indent+2 and lines[index][1].startswith('- '):
                        item[key], index = parse(index, lines[index][0])
                    else:
                        item[key] = None
                    if index < len(lines) and lines[index][0] > indent:
                        rest, index = parse(index, lines[index][0])
                        if isinstance(rest, dict):
                            item.update(rest)
                    result.append(item)
                elif val:
                    result.append(scalar(val))
                elif index < len(lines) and lines[index][0] > indent:
                    item, index = parse(index, lines[index][0])
                    result.append(item)
                else:
                    result.append(None)
            else:
                p = mapping_pair(s)
                if not p:
