import re
import json
import math


def split_flow(s, delimiter=','):
    out, start, depth, quote = [], 0, 0, ''
    i = 0
    while i < len(s):
        c = s[i]
        if quote:
            if c == quote:
                if quote == "'" and i+1 < len(s) and s[i+1] == "'":
                    i += 1
                else:
                    quote = ''
            elif c == '\\' and quote == '"':
                i += 1
        elif c in "\"'":
            quote = c
        elif c in '[{(':
            depth += 1
        elif c in ']})':
            depth -= 1
        elif c == delimiter and depth == 0:
            out.append(s[start:i].strip())
            start = i+1
        i += 1
    out.append(s[start:].strip())
    return out


def mapping_pair(s):
    depth, quote = 0, ''
    for i, c in enumerate(s):
        if quote:
            if c == quote and (i == 0 or s[i-1] != '\\'):
                quote = ''
        elif c in "\"'":
            quote = c
        elif c in '[{':
            depth += 1
        elif c in ']}':
            depth -= 1
        elif c == ':' and depth == 0 and (i+1 == len(s) or s[i+1].isspace()):
            return s[:i], s[i+1:].strip()
    return None


