    text = text.strip()
    if not text or text.lower() in ('null', '~'):
        return None
    if text[:1] == '"' and text[-1:] == '"':
        try:
            return json.loads(text)
        except Exception:
            return text[1:-1]
    if text[:1] == "'" and text[-1:] == "'":
        return text[1:-1].replace("''", "'")
    if text.startswith('[') and text.endswith(']'):
        return [scalar(v) for v in split_flow(text[1:-1])] if text[1:-1].strip() else []
    if text.startswith('{') and text.endswith('}'):
        out = {}
        for part in split_flow(text[1:-1]):
            if not part:
                continue
            pair = mapping_pair(part)
            if not pair and ':' in part:
                pair = part.split(':', 1)
            if pair:
                out[str(scalar(pair[0]))] = scalar(pair[1])
            else:
                out[str(scalar(part))] = None
