def json_dump(v, indent=None, level=0):
    if v is None: return 'null'
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v, (int,float)): return number(v, True)
    if isinstance(v, str): return json_string(v)
    if isinstance(v, bytes): return json_string('\\x'+v.hex())
    if isinstance(v, (list,dict)):
        left, right = ('{','}') if isinstance(v,dict) else ('[',']')
        if not v: return left+right
        gap = ': ' if indent is not None else ':'
        parts = [json_string(str(k))+gap+json_dump(x,indent,level+1) for k,x in v.items()] if isinstance(v,dict) else [json_dump(x,indent,level+1) for x in v]
        if indent is None: return left+','.join(parts)+right
        return left+'\n'+',\n'.join(' '*(indent*(level+1))+p for p in parts)+'\n'+' '*(indent*level)+right
    return json_string(str(v))


def structured(v, opt):
    if isinstance(v, str):
        if v.startswith(('[','{')):
            try: return json.loads(v)
            except (ValueError, TypeError): pass
        return v
    if isinstance(v, bytes):
        return '\\x'+v.hex()
    if opt.get('onull') is not None:
        return opt['onull']
    return v


def rune(s, default):
    if len(s) <= 1:
        return s or '\x00'
    escapes = {'\\t':'\t','\\n':'\n','\\r':'\r','\\a':'\a','\\b':'\b','\\f':'\f','\\v':'\v','\\\\':'\\', '\\"':'"', "\\'":"'"}
    if s in escapes: return escapes[s]
    try:
        if re.fullmatch(r'\\x[0-9a-fA-F]{2}|\\u[0-9a-fA-F]{4}|\\U[0-9a-fA-F]{8}', s):
