    names = [string(x) for x in names]
    data = [[string(v,null) for v in row] for row in rows]
    if markdown:
        names = [s.replace('|','\\|') for s in names]
        data = [[s.replace('|','\\|') for s in r] for r in data]
    allrows = [names]+data
