    # indivisible words.  Explicit line breaks are considered independently.
    widths = [0]*len(names)
    cells = []
    for row in allrows:
        cr = []
        for i,s in enumerate(row):
            lines = s.replace('\r\n','\n').split('\n')
            w = max([width(x) for x in lines]+[0])
            if not nowrap and w > 30:
                w = max(30, max([width(x) for x in s.split()]+[0]))
            widths[i] = max(widths[i], w)
            cr.append([t for line in lines for t in (word_wrap(line) if not nowrap else [line])])
