        for j in range(height):
            values = []
            for i,c in enumerate(row):
                s = c[j] if j<len(c) else ''
                align = 'center' if ri==0 else ('right' if numeric(s) else 'left')
                values.append(' '+pad(s,widths[i],align)+' ')
