        s = string(v)
        need = opt.get('oaq') or s == '\\.' or (s and (s[0].isspace() or any(c in s for c in (delimiter,quote,'\r','\n'))))
        if need:
            if opt.get('ocrlf'):
                s = s.replace('\r','').replace('\n','\r\n')
            s = quote + s.replace(quote, quote*2) + quote
