    return sum(0 if unicodedata.combining(c) or unicodedata.category(c) in ('Cc','Cf','Mn','Me') else 2 if unicodedata.east_asian_width(c) in ('W','F') else 1 for c in re.sub(r'\x1b\[[0-9;]*m','',s))


