    n = max(n-width(s),0)
    if align == 'right': return ' '*n+s
    if align == 'center':
        return ' '*(n//2)+s+' '*(n-n//2)
    return s+' '*n


def numeric(s):
    if not s or s.strip() != s: return False
    try:
        float(s)
        return True
    except ValueError: return False


def word_wrap(s, limit=30):
    if width(s) <= limit: return [s]
    # Keep unbroken words intact, just as in a terminal table.
    words = s.split()
    if not words: return [s]
    out, line = [], ''
    for word in words:
        if line and width(line+' '+word) > limit:
            out.append(line)
            line = word
        else:
            line = (line+' ' if line else '')+word
    if line: out.append(line)
    return out


def table(names, rows, markdown=False, nowrap=False, null=''):
    names = [string(x) for x in names]
    data = [[string(v,null) for v in row] for row in rows]
    if markdown:
        names = [s.replace('|','\\|') for s in names]
        data = [[s.replace('|','\\|') for s in r] for r in data]
    allrows = [names]+data
    # Width is determined before word wrapping, capped at thirty except for
    # indivisible words.  Explicit line breaks are considered independently.
    widths = [0]*len(names)
    cells = []
    for row in allrows:
        cr = []
        for i,s in enumerate(row):
            lines = s.replace('\r\n','\n').split('\n')
            w = max([width(x) for x in lines]+[0])
            if not nowrap and w > 30:
                w = max(30, max([width(x) for x in s.split()]+[0]))
            widths[i] = max(widths[i], w)
            cr.append([t for line in lines for t in (word_wrap(line) if not nowrap else [line])])
        cells.append(cr)
    border = ('|' if markdown else '+')+('|' if markdown else '+').join('-'*(w+2) for w in widths)+('|' if markdown else '+')+'\n'
    result = '' if markdown else border
    for ri, row in enumerate(cells):
        height = max([len(c) for c in row]+[1])
        for j in range(height):
            values = []
            for i,c in enumerate(row):
                s = c[j] if j<len(c) else ''
                align = 'center' if ri==0 else ('right' if numeric(s) else 'left')
                values.append(' '+pad(s,widths[i],align)+' ')
            result += '|'+ '|'.join(values)+'|\n'
        if ri==0:
            result += border
    if not markdown: result += border
    return result


def yaml_value(v, opt):
    if not isinstance(v,(str,bytes)):
        if opt.get('onull') is not None:
            v = opt['onull']
        else:
            return v
    if isinstance(v,bytes):
        return v.decode('utf-8','replace')
    # Values are interpreted as individual YAML expressions on export.
    s = v.replace('\t','')
    if not s.strip(): return None
    try: return yaml_codec.load_one(s)
    except Exception: return s


def render(names, rows, opt, fmt=None):
    fmt = fmt or opt.get('output','csv')
    null = opt.get('onull') or ''
    if fmt in ('json','jsonl','yaml'):
        values=[]
        for row in rows:
            item={}
            for n,v in zip(names,row):
                item[n]=yaml_value(v,opt) if fmt=='yaml' else structured(v,opt)
            values.append(item)
        if fmt=='yaml': return yaml_codec.dump(values)
        if fmt=='jsonl': return ''.join(json_dump(v)+'\n' for v in values)
        return json_dump(values,2)+'\n'
    if fmt=='csv':
        return (csv_line(names,opt,True) if opt.get('oh') else '')+''.join(csv_line(row,opt) for row in rows)
    if fmt=='raw':
        sep=rune(opt.get('od',','),',')
        return (csv_line(names,opt,True) if opt.get('oh') else '')+''.join(sep.join(string(v,null) for v in row)+'\n' for row in rows)
    if fmt=='ltsv':
        return ''.join('\t'.join(n+':'+string(v,null) for n,v in zip(names,row))+'\n' for row in rows)
    if fmt in ('at','md'):
        return table(names,rows,fmt=='md',opt.get('onowrap',False),null)
    if fmt=='vf':
        w=max([len(n.encode('utf-8')) for n in names]+[0])
        return ''.join('---[%2d]------------------------\n'%(i+1)+''.join('  '+(' '*(w-len(n.encode('utf-8'))))+n+' | '+string(v,null)+'\n' for n,v in zip(names,row)) for i,row in enumerate(rows))
    if fmt=='tbln':
        def line(values):
            return '| '+' | '.join(string(v,null).replace('\n','\\n') for v in values)+' |\n'
        return '; name: '+line(names)+'; type: '+line(['text']*len(names))+''.join(line(r) for r in rows)
    return ''
