"""A compact expression evaluator for selecting records from JSON inputs."""
import json
import re
from yaml_codec import split_flow


class JQError(Exception):
    pass


def split_top(s, char):
    return split_flow(s,char)


def evaluate(expr, value):
    expr=expr.strip()
    if not expr or expr=='.': return [value]
    pipes=split_top(expr,'|')
    if len(pipes)>1:
        vals=[value]
        for p in pipes:
            vals=[v for x in vals for v in evaluate(p,x)]
        return vals
    commas=split_top(expr,',')
    if len(commas)>1:
        return [v for p in commas for v in evaluate(p,value)]
    if expr.startswith('(') and expr.endswith(')'):
        return evaluate(expr[1:-1],value)
    if expr.startswith('[') and expr.endswith(']'):
        return [[v for v in evaluate(expr[1:-1],value)]] if expr[1:-1].strip() else [[]]
    if expr.startswith('{') and expr.endswith('}'):
        obj={}
        for item in split_top(expr[1:-1],','):
            if ':' in item:
                k,x=item.split(':',1)
                k=k.strip().strip('"')
            else:
                k=item.strip().strip('"');x='.'+k
            vals=evaluate(x,value)
            obj[k]=vals[0] if vals else None
        return [obj]
    if expr.startswith('select(') and expr.endswith(')'):
        return [value] if condition(expr[7:-1],value) else []
    if expr.startswith('map(') and expr.endswith(')'):
        return [[v for x in (value or []) for v in evaluate(expr[4:-1],x)]]
    if expr in ('empty',): return []
    if expr in ('length',):
        return [len(value) if isinstance(value,(str,list,dict)) else abs(value) if isinstance(value,(float,int)) else 0]
    if expr in ('keys','keys_unsorted'):
        return [sorted(value) if isinstance(value,dict) and expr=='keys' else list(value) if isinstance(value,dict) else list(range(len(value)))]
    if expr=='values':return [] if value is None else [value]
    if expr=='tostring':return [value if isinstance(value,str) else json.dumps(value,separators=(',',':'),ensure_ascii=False)]
    if expr=='tonumber':
        try:return [float(value) if '.' in str(value) else int(value)]
        except Exception:raise JQError('cannot parse number: '+repr(value))
    if expr in ('add','sort','unique','reverse'):
        if expr=='add':
            if not value:return [None]
            x=value[0]
            for v in value[1:]:x+=v
            return [x]
        if expr=='sort':return [sorted(value)]
        if expr=='reverse':return [list(reversed(value))]
        return [sorted(set(value))]
    m=re.fullmatch(r'(sort_by|group_by|unique_by)\((.*)\)',expr,re.S)
    if m:
        key=lambda x:evaluate(m[2],x)[0]
        vals=sorted(value,key=key)
        if m[1]=='sort_by':return [vals]
        groups=[]
        for v in vals:
            if groups and key(groups[-1][0])==key(v):groups[-1].append(v)
            else:groups.append([v])
        return [groups if m[1]=='group_by' else [g[0] for g in groups]]
    if expr.startswith('.'):
        vals=[value];rest=expr[1:]
        while rest:
            if rest.startswith('.'):
                rest=rest[1:];continue
            if rest.startswith('?'):
                rest=rest[1:];continue
            if rest.startswith('['):
                end=rest.find(']')
                if end<0:raise JQError('unexpected EOF')
                sub=rest[1:end].strip();rest=rest[end+1:]
                new=[]
                for v in vals:
                    if not sub:
                        if isinstance(v,dict):new.extend(v.values())
                        elif isinstance(v,list):new.extend(v)
                        elif v is not None:raise JQError('cannot iterate over: '+str(v))
                    elif ':' in sub:
                        p=sub.split(':');a=int(p[0]) if p[0] else None;b=int(p[1]) if p[1] else None
                        new.append(v[a:b] if v is not None else None)
                    else:
                        try:k=json.loads(sub)
                        except Exception:k=sub.strip('"')
                        try:new.append(v[k])
                        except (KeyError,IndexError,TypeError):new.append(None)
                vals=new;continue
            m=re.match(r'([\w$]+|"(?:[^"\\]|\\.)*")',rest)
            if not m:raise JQError('unexpected token "'+rest+'"')
            k=m[0].strip('"');rest=rest[len(m[0]):]
            new=[]
            for v in vals:
                if isinstance(v,dict):new.append(v.get(k))
                elif v is None:new.append(None)
                else:
                    t='array' if isinstance(v,list) else 'string' if isinstance(v,str) else 'number'
                    short=json.dumps(v,separators=(',',':'),ensure_ascii=False)
                    if len(short)>25:short=short[:25]+' ...'
                    raise JQError('expected an object but got: '+t+' ('+short+')')
            vals=new
        return vals
    try:return [json.loads(expr)]
    except ValueError:pass
    if re.fullmatch(r'[a-zA-Z_]\w*',expr):
        raise JQError('function not defined: '+expr+'/0')
    raise JQError('unexpected token "'+expr+'"')


def condition(expr,value):
    expr=expr.strip()
    for op in (' or ',' and '):
        if op in expr:
            parts=expr.split(op)
            return any(condition(p,value) for p in parts) if op.strip()=='or' else all(condition(p,value) for p in parts)
    m=re.match(r'(.*?)(==|!=|>=|<=|>|<)(.*)',expr,re.S)
    if m:
        a=evaluate(m[1],value);b=evaluate(m[3],value)
        a=a[0] if a else None;b=b[0] if b else None
        try:return {'==':lambda:a==b,'!=':lambda:a!=b,'>':lambda:a>b,'<':lambda:a<b,'>=':lambda:a>=b,'<=':lambda:a<=b}[m[2]]()
        except TypeError:return False
    m=re.fullmatch(r'has\("(.*)"\)',expr)
    if m:return m[1] in value
    vals=evaluate(expr,value)
    return bool(vals) and vals[0] is not None and vals[0] is not False
