        for sql in split_statements(query):
            if not sql:raise Failure('export: no SQL statement')
            sql=self.rewrite(sql)
            try:
                cur=self.conn.execute(sql)
                head=tokens(sql)
                exporting=bool(head and head[0][2].upper()=='SELECT')
                if exporting and cur.description:
                    names=[d[0] for d in cur.description]
                    rows=cur.fetchall()
                    yield render(names,rows,self.opts)
                elif cur.description:
                    cur.fetchall()
            except sqlite3.Error as exc:raise Failure('export: '+str(exc)+' ['+sql+']')


RESERVED=set('all alter analyze and as asc between by case cast check collate column constraint create cross current_date current_time current_timestamp default delete desc distinct drop else end escape except exists false foreign from full group having in index inner insert intersect into is join key left like limit natural not null offset on or order outer primary references right select set table then true union unique update using values value when where with'.split())

def suggestion_name(s):
    if not re.fullmatch(r'[A-Za-z_][A-Za-z_0-9]*',s) or s.lower() in RESERVED:
        return '\\`'+s.replace('`','\\`')+'\\`'
    return s


def analyze(opts,argv):
    name=opts.get('A') or opts.get('a')
    try:tab=load(name,opts,[None])
    except FileNotFoundError:raise Failure('ERROR: open '+name+': no such file or directory')
    except ImportFailure as exc:raise Failure('ERROR: '+str(exc))
    except OSError as exc:raise Failure('ERROR: '+str(exc))
    names=[suggestion_name(x) for x in tab.names]
    args=[];skip=False
    for arg in argv:
        if skip:skip=False;continue
        if arg in ('-a','-A','--a','--A'):skip=True;continue
        if arg.startswith(('-a=','-A=','--a=','--A=')):continue
        args.append(arg)
    prog=sys.argv[0]
    pre=prog+(' '+' '.join(args) if args else '')+' '
    cols=', '.join(names);first=names[0] if names else ''
    example=string(tab.samples[0][0]) if tab.samples and tab.samples[0] else ''
    qtable=name
    examples=[f'SELECT {cols} FROM {qtable}',f"SELECT {cols} FROM {qtable} WHERE {first} = '{example}'",f'SELECT {first}, count({first}) FROM {qtable} GROUP BY {first}',f'SELECT {cols} FROM {qtable} ORDER BY {first} LIMIT 10']
    output=''
    if not opts.get('A'):
        output='The table name is '+name+'.\nThe file type is '+tab.format+'.\n\nData types:\n'
        output+=table(['column name','type'],list(zip(names,tab.types)))
        output+='\nData samples:\n'+table(names,tab.samples)
        output+='\nExamples:\n'
    output+=''.join(pre+'"'+q+'"\n' for q in examples)
    return output


def compress(data,kind):
    if kind=='gz':return gzip.compress(data,mtime=0)
    if kind=='bz2':return bz2.compress(data)
    if kind=='xz':return lzma.compress(data)
    if kind in ('zst','zstd','lz4'):
        from compression import compress as f
        return f(data,kind)
    return data


def main():
    opts,args=parse_flags(sys.argv[1:])
    if opts.get('version'):
        sys.stdout.write('trdsql version devel\n');return
    if opts.get('help'):usage()
    config_options(opts)
    output_options(opts)
    if opts.get('a') or opts.get('A'):
        sys.stdout.write(analyze(opts,sys.argv[1:]));return
    query=' '.join(args)
    if opts.get('q'):
        filename=opts['q']
        try:
            query=sys.stdin.read() if filename=='-' else Path(filename).read_text()
        except FileNotFoundError:raise Failure('ERROR: open '+filename+': no such file or directory')
        except OSError as exc:raise Failure('ERROR: '+str(exc))
    if opts.get('t'):
        name=opts['t']
        query='SELECT * FROM '+('"'+name.replace('"','""')+'"' if any(c.isspace() for c in name) else name)
    if not query:usage()
    conn=connect(opts);engine=Engine(opts,conn)
    outname=opts.get('out');sink=None;close=False
    kind=opts.get('oz','')
    if not kind and outname:
        ext=os.path.splitext(outname.lower())[1]
        if ext in ('.gz','.bz2','.xz','.zst','.zstd','.lz4'):kind=ext[1:]
    try:
        if outname:
            try:sink=open(outname,'wb');close=True
            except OSError as exc:raise Failure('export: open '+outname+': '+exc.strerror.lower())
        else:sink=sys.stdout.buffer
        buffered=[]
        for text in engine.execute(query):
            data=text.encode('utf-8','replace')
            if kind:buffered.append(data)
            else:sink.write(data);sink.flush()
        if kind:sink.write(compress(b''.join(buffered),kind))
        conn.commit()
    finally:
        if close:sink.close()
        conn.close()


if __name__=='__main__':
    try:
        main()
    except Failure as exc:
        log(str(exc));sys.exit(1)
    except BrokenPipeError:
        sys.exit(1)
    except KeyboardInterrupt:
        sys.exit(130)
