// This small independent codec keeps gzip framing consistent across platforms.
// It is built entirely with the Go standard library, without external modules.
package main

import (
    "compress/gzip"
    "io"
    "os"
)

func main() {
    writer := gzip.NewWriter(os.Stdout)
    if _, err := io.Copy(writer, os.Stdin); err != nil {
        os.Exit(1)
    }
    if err := writer.Close(); err != nil {
        os.Exit(1)
    }
}
